    def _create_link(self, now, token_hash, slug, body):
        store = self.server.store
        try:
            url, slug, exp = links.validate_create(body)
        except ValueError as e:
            raise ApiError(400, "invalid_request", str(e))
        expires_at = None if exp is None else now + exp
        if slug is not None:
            if slug == links.RESERVED:
                raise ApiError(409, "slug_taken", "slug is taken")
        else:
            for _ in range(5):
                slug = links.generate_slug()
                if slug != links.RESERVED and not store.slug_exists(slug):
                    break
            else:
                raise ApiError(500, "internal", "could not generate a slug")
        try:
            store.add_link(slug, url, token_hash, now, expires_at)
        except SlugTaken:
            raise ApiError(409, "slug_taken", "slug is taken")
        self._respond(201, links.link_object(store.get_link(slug, token_hash), self.server.port))

    def _list_links(self, now, token_hash, slug, body):
        rows = self.server.store.list_links(token_hash)
        self._respond(200, {"links": [links.link_object(r, self.server.port) for r in rows]})

    def _get_link(self, now, token_hash, slug, body):
        row = self.server.store.get_link(slug, token_hash)
        if row is None:
            raise ApiError(404, "not_found", "not found")
        self._respond(200, links.link_object(row, self.server.port))

    def _delete_link(self, now, token_hash, slug, body):
        if not self.server.store.delete_link(slug, token_hash):
            raise ApiError(404, "not_found", "not found")
        self._respond(204)

    def _resolve(self, now, token_hash, slug, body):
        status, url = self.server.store.resolve(slug, now)
        if status == "missing":
            raise ApiError(404, "not_found", "not found")
        if status == "gone":
            raise ApiError(410, "gone", "link has expired")
        self._respond(302, headers={"Location": url.encode("utf-8").decode("latin-1")})


def _reject_constant(name):
    raise ValueError(name)
